Here is the commit message:
fix bug introduced by
 7cef6c46552a988c1c710a0a2404316a27ef1d43 stack_start used to be stack_start +
 stack_size, so re-setting stk to stack_start would set the pointer to the
 *end* of the stack instead of the beginning.

Here is the root cause:
The bug was caused by the incorrect calculation of the stack pointer's initial position. The original code added the stack size to the stack start address without proper parentheses, leading to the stack pointer pointing to the end of the stack instead of the beginning. This miscalculation resulted in incorrect stack initialization, potentially causing stack corruption or crashes during task execution.

Here is the patch:
 //----------------------------------------------------------------------------
 char * thread_stack_init(void * task_func, void * stack_start, int stack_size)
 {
    unsigned int * stk;
-   stk = (unsigned int *) stack_start + stack_size;
+   stk = (unsigned int *) (stack_start + stack_size);
     stk--;

     *stk = 0x77777777;
     stk--;

     *stk = (unsigned int)sched_task_exit;       // LR

    stk--;
-   *stk = (unsigned int) stack_start - 4;   // SP
+   *stk = (unsigned int) (stack_start + stack_size) - 4;   // SP

    for (int i = 12; i>= 0 ; i--) {          // build base stack
        stk--;
        *stk = i;
    }

    stk--;
    *stk = ((unsigned int) task_func);       // Entry Point
    stk--;
    *stk = (unsigned int) NEW_TASK_CPSR;     // spsr

    return (char*)stk;
 }



